refs.forEach(function(r){ svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(r), y2: yp(r), stroke: r > 0 ? "#2e7d32" : "#7a3030", "stroke-dasharray": "3,3", "stroke-width": 1})); });
